UPDATE erp_attachments SET record_id=(SELECT p.id FROM erp_payment_requests p WHERE p.request_no=erp_attachments.record_no)
 WHERE record_type='PAYMENT_REQUEST' AND record_id IS NULL AND record_no IS NOT NULL;
UPDATE erp_payment_request_lines SET payment_request_id=(SELECT p.id FROM erp_payment_requests p WHERE p.request_no=erp_payment_request_lines.rfp_ref)
 WHERE payment_request_id IS NULL;
